<script setup>
import {ref,computed} from 'vue';
import {useI18n} from '../lib/i18n.js';
import {makeArrangement,placeToken,returnToken,arrangedBoxes,tileWrong,tileState} from '../lib/arrange-letters.js';
import {boxAnswer,boxesComplete,answerDirection} from '../lib/letter-boxes.js';
import LetterBoxes from './LetterBoxes.vue';
const props=defineProps({expected:String,disabled:Boolean,liveFeedback:Boolean,direction:String,modelValue:String});
const emit=defineEmits(['update:modelValue','committed-error']);const {t}=useI18n();
const initial=makeArrangement(props.expected);
const state=ref(initial&&initial.tokens.length>0&&initial.slots.length<=240?initial:null);const boxes=computed(()=>state.value?arrangedBoxes(state.value):[]);
const used=computed(()=>new Set(state.value?.slots.map(slot=>slot.token)));
function update(next){if(props.disabled)return;state.value=next;if(props.liveFeedback&&boxes.value.some(tileWrong))emit('committed-error');emit('update:modelValue',boxesComplete(boxes.value)?boxAnswer(boxes.value):'');}
</script>
<template><div v-if="state" class="arrangement"><p class="muted small">{{t('Tap letters to build your answer. Tap a placed letter to return it.')}}</p><div class="arrange-slots" :dir="answerDirection(expected,direction)"><template v-for="(box,index) in boxes" :key="index"><span v-if="box.fixed" class="arrange-cell fixed">{{box.text}}</span><button v-else type="button" :disabled="disabled||box.token===null" :class="['arrange-cell',liveFeedback?tileState(box):'']" :aria-label="t('Letter {number}: {letter}',{number:index+1,letter:box.value||t('blank')})+(liveFeedback&&tileState(box)?': '+t(tileState(box)==='incorrect'?'Incorrect placement':'Correct placement'):'')" @click="update(returnToken(state,index))">{{box.value||' '}}<span v-if="liveFeedback&&tileState(box)" class="placement-mark" aria-hidden="true">{{tileState(box)==='incorrect'?'×':'✓'}}</span></button></template></div><div class="arrange-bank" :dir="answerDirection(expected,direction)" :aria-label="t('Available letters')"><button v-for="token in state.tokens" :key="token.id" type="button" class="arrange-cell" :disabled="disabled||used.has(token.id)" :aria-label="t('Place letter {letter}',{letter:token.text})" @click="update(placeToken(state,token.id))">{{token.text}}</button></div></div><p v-if="!state" class="muted small">{{t('Use a written answer for very long text or when letter tiles are unavailable.')}}</p><LetterBoxes v-if="!state" :expected="expected" :model-value="modelValue" :disabled="disabled" :direction="direction" :live-feedback="liveFeedback" @update:model-value="emit('update:modelValue',$event)" @committed-error="emit('committed-error')"/></template>
<style scoped>
.arrange-slots,.arrange-bank{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:.3rem;unicode-bidi:isolate;margin:1rem 0}.arrange-bank{padding-top:1rem;border-top:1px solid var(--practice-border,#b6ddc8)}.arrange-cell{position:relative;min-width:0;min-height:44px;padding:.2rem;font-size:1.1rem;border:1px solid var(--practice-border,#b6ddc8);background:white;color:var(--practice-ink,#164b3c);border-radius:.5rem;overflow-wrap:anywhere}.arrange-cell.fixed{display:grid;place-items:center;white-space:pre-wrap;background:var(--practice-soft,#e9f7ef)}.arrange-cell:focus-visible{outline:3px solid var(--practice-focus,#17644d);outline-offset:2px}.arrange-bank .arrange-cell:disabled{opacity:.3}.arrange-cell.correct{border:2px solid var(--practice-accent,#17644d);background:var(--practice-soft,#e9f7ef)}.arrange-cell.incorrect{border:2px solid #a42f36;background:#fff0f1}.placement-mark{position:absolute;right:1px;bottom:0;font-size:.7rem;font-weight:bold}
</style>
